const graph = { A: ["B", "C"], B: ["A"], C: ["A"] };

function walk(node, budget) {
  if (budget === 0) return [];
  let out = [node];
  for (const nb of graph[node]) out = out.concat(walk(nb, budget - 1));
  return out;
}
console.log("no visited set, budget 4:", walk("A", 4).join(" "));

function walkSafe(node, visited) {
  if (visited.has(node)) return [];
  visited.add(node);
  let out = [node];
  for (const nb of graph[node]) out = out.concat(walkSafe(nb, visited));
  return out;
}
console.log("with a visited set:", walkSafe("A", new Set()).join(" "));

const CISTERN = {
  A: ["B", "C"], B: ["A", "D"], C: ["A", "D", "E"],
  D: ["B", "C", "F"], E: ["C", "F"], F: ["D", "E"]
};

function bfs(graph, start) {
  const visited = new Set([start]);
  const dist = { [start]: 0 };
  const queue = [start];
  const order = [];
  while (queue.length > 0) {
    const node = queue.shift();
    order.push(node);
    for (const nb of graph[node]) {
      if (visited.has(nb)) continue;
      visited.add(nb);
      dist[nb] = dist[node] + 1;
      queue.push(nb);
    }
  }
  return { order, dist };
}

const r = bfs(CISTERN, "A");
console.log("visit order:", r.order.join(" "));
console.log("distances:", JSON.stringify(r.dist));

