function bfsDistances(graph, start) {
  const dist = { [start]: 0 };
  const queue = [start];
  while (queue.length > 0) {
    const node = queue.shift();
    for (const nb of graph[node] || []) {
      if (nb in dist) continue;
      dist[nb] = dist[node] + 1;
      queue.push(nb);
    }
  }
  return dist;
}

