  const visited = new Set();
  let count = 0;
  for (const start of Object.keys(graph)) {
    if (visited.has(start)) continue;
    count++;
    const stack = [start];
    while (stack.length > 0) {
      const node = stack.pop();
      if (visited.has(node)) continue;
      visited.add(node);
      for (const nb of graph[node] || []) stack.push(nb);
    }
  }
  return count;
}

