    const node = queue.shift();
    if (dist[node] === d) out.push(node);
    for (const nb of graph[node] || []) {
      if (visited.has(nb)) continue;
      visited.add(nb);
      dist[nb] = dist[node] + 1;
      queue.push(nb);
    }
  }
  return out.sort();
}

